package com.secops.service;
import com.secops.config.SecOpsProperties; import com.secops.entity.*; import com.secops.exception.PolicyViolationException; import com.secops.guardrail.PolicyGuardrailService; import com.secops.mapper.ConversationMapper; import com.secops.orchestration.SecOpsOrchestrator; import com.secops.repository.*; import com.secops.security.SecOpsPrincipal; import org.junit.jupiter.api.Test; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class ConversationServiceEarlyExitTest { @Test void biasStopsBeforePiiAndOrchestrator(){var conversations=mock(ConversationRepository.class);var messages=mock(MessageRepository.class);var pii=mock(PiiTokenizationService.class);var orchestrator=mock(SecOpsOrchestrator.class);var id=UUID.randomUUID();var userId=UUID.randomUUID();var c=new Conversation();c.setId(id);c.setOwnerId(userId);when(conversations.findByIdAndOwnerId(id,userId)).thenReturn(Optional.of(c));var props=new SecOpsProperties(null,null,null,null,null,null,false,new SecOpsProperties.Policy(8000,"nacionalidad","system prompt"));var svc=new ConversationService(conversations,messages,new ConversationMapper(),new PolicyGuardrailService(props),pii,orchestrator,mock(EncryptionService.class),mock(HashingService.class),mock(AuditService.class));assertThrows(PolicyViolationException.class,()->svc.send(new SecOpsPrincipal(userId,"u",Set.of(Role.USER)),id,"Prioriza por nacionalidad"));verifyNoInteractions(pii,orchestrator,messages);}}
